ON CONFLICT (workspace_id, code) DO UPDATE SET
  display_name = EXCLUDED.display_name,
  offering_type = EXCLUDED.offering_type,
  status = EXCLUDED.status,
  description = EXCLUDED.description,
  value_proposition = EXCLUDED.value_proposition,
  price_type = EXCLUDED.price_type,
  price_amount = EXCLUDED.price_amount,
  currency = EXCLUDED.currency,
  billing_interval = EXCLUDED.billing_interval,
  audience = EXCLUDED.audience,
  delivery = EXCLUDED.delivery,
  guardrails = EXCLUDED.guardrails,
  metadata = EXCLUDED.metadata,
  updated_at = now();

UPDATE offerings
SET status = 'inactive',
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'deactivated_by_catalog_sync', 'studyx_manual_1',
      'deactivated_at', now()
    ),
    updated_at = now()
WHERE workspace_id = 'b0000000-0000-4000-8000-000000000001'::uuid
  AND code NOT IN ('vino_cata_maridaje', 'introduccion_catering', 'sushi_principiantes', 'entrenamiento_funcional', 'nutricion_alimentacion', 'marketing_digital', 'community_manager', 'especialista_marketing', 'introduccion_ecommerce', 'fotografia_celulares_tiendas_online', 'influencers_creadores_contenidos', 'publicidad_redes_sociales', 'maquillaje_profesional', 'unas_gelificadas', 'camaras_seguridad', 'aires_acondicionados', 'energia_solar_fotovoltaica', 'armado_reparacion_pc', 'reparacion_celulares', 'redes_informaticas', 'decoracion_de_interiores', 'fotografia_profesional', 'organizador_eventos_sociales', 'organizacion_baby_shower', 'paisajismo_jardineria', 'estrategias_emprender', 'instagram_emprendedores', 'diseno_corel_draw', 'diseno_photoshop', 'diseno_illustrator', 'autocad_interiores', 'excel_integral', 'especialista_ventas', 'coaching_liderazgo', 'comunicacion_interna_empresas', 'introduccion_criptomonedas', 'oratoria', 'ingles_1', 'ingles_2', 'ingles_3')
  AND status = 'active';

-- Retire website-derived course sources so retrieval has one catalog truth.
UPDATE knowledge_sources
SET status = 'archived', updated_at = now()
WHERE workspace_id = 'b0000000-0000-4000-8000-000000000001'::uuid
  AND source_type = 'offering'
  AND COALESCE(metadata ->> 'canonical_source', '') <> 'studyx_manual_1'
  AND status <> 'archived';

-- Retire general statements that conflict with the owner-declared manual.
UPDATE knowledge_sources
SET status = 'archived', updated_at = now()
WHERE workspace_id = 'b0000000-0000-4000-8000-000000000001'::uuid
  AND title IN (
    'Qué vende StudyX',
    'Tamaño real del catálogo y qué no afirmar',
    'Modalidad: qué se puede afirmar sobre las clases'
  )
  AND status <> 'archived';

